                                                                                                                                                                            'rust',
                                                                                                                                                                            'easy',
                                                                                                                                                                            'use std::io;\n\nfn is_balanced(s: &str) -> bool {\n    let mut stack = Vec::new();\n    for c in s.chars() {\n        match c {\n            ''('' | ''['' | ''{'' => stack.push(c),\n            '')'' => if stack.pop() != Some(''('') { return false; },\n            '']'' => if stack.pop() != Some(''['') { return false; },\n            ''}'' => if stack.pop() != Some(''{'') { return false; },\n            _ => {}\n        }\n    }\n    stack.is_empty()\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    println!("{}", if is_balanced(input.trim()) { "yes" } else { "no" });\n}\n',
                                                                                                                                                                            'use std::io;\n\nfn is_balanced(s: &str) -> bool {\n    let mut stack: Vec<char> = Vec::new();\n    for c in s.chars() {\n        match c {\n            ''('' | ''['' | ''{'' => stack.push(c),\n            '')'' | '']'' | ''}'' => {\n                if stack.is_empty() { return false; }\n                stack.pop();\n            },\n            _ => {}\n        }\n    }\n    stack.is_empty()\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    println!("{}", if is_balanced(input.trim()) { "yes" } else { "no" });\n}\n',
