                                                                                                                                                                            'Matrix Diagonal Sum',
                                                                                                                                                                            ARRAY['arrays', 'math'],
                                                                                                                                                                            'rust',
                                                                                                                                                                            'easy',
                                                                                                                                                                            'use std::io;\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let n: usize = input.trim().parse().unwrap();\n    let mut matrix = Vec::with_capacity(n);\n    for _ in 0..n {\n        let mut row = String::new();\n        io::stdin().read_line(&mut row).unwrap();\n        let r: Vec<i64> = row.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n        matrix.push(r);\n    }\n    let mut sum: i64 = 0;\n    for i in 0..n {\n        sum += matrix[i][i];\n        sum += matrix[i][n - 1 - i];\n    }\n    if n % 2 == 1 {\n        sum -= matrix[n/2][n/2];\n    }\n    println!("{}", sum);\n}\n',
                                                                                                                                                                            'use std::io;\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let n: usize = input.trim().parse().unwrap();\n    let mut matrix = Vec::with_capacity(n);\n    for _ in 0..n {\n        let mut row = String::new();\n        io::stdin().read_line(&mut row).unwrap();\n        let r: Vec<i64> = row.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n        matrix.push(r);\n    }\n    let mut sum: i64 = 0;\n    for i in 0..n {\n        sum += matrix[i][i];\n        sum += matrix[i][n - 1 - i];\n    }\n    println!("{}", sum);\n}\n',
