                                                                                                                                                                            'rust',
                                                                                                                                                                            'easy',
                                                                                                                                                                            'use std::io;\n\nfn to_camel(s: &str) -> String {\n    let mut result = String::new();\n    let mut capitalize = false;\n    for c in s.chars() {\n        if c == ''_'' {\n            capitalize = true;\n        } else if capitalize {\n            result.extend(c.to_uppercase());\n            capitalize = false;\n        } else {\n            result.push(c);\n        }\n    }\n    result\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    println!("{}", to_camel(input.trim()));\n}\n',
                                                                                                                                                                            'use std::io;\n\nfn to_camel(s: &str) -> String {\n    let parts: Vec<&str> = s.split(''_'').collect();\n    let mut result = String::new();\n    for p in parts {\n        result.push_str(p);\n    }\n    result\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    println!("{}", to_camel(input.trim()));\n}\n',
