                                                                                                                                                                            'rust',
                                                                                                                                                                            'medium',
                                                                                                                                                                            'use std::io;\nuse std::collections::HashSet;\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let nums: Vec<i32> = input.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let mut seen = HashSet::new();\n    for n in &nums {\n        if !seen.insert(*n) {\n            println!("{}", n);\n            return;\n        }\n    }\n    println!("-1");\n}\n',
                                                                                                                                                                            'use std::io;\nuse std::collections::HashSet;\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let nums: Vec<i32> = input.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let mut seen = HashSet::new();\n    let mut dup: Option<i32> = None;\n    for n in &nums {\n        if !seen.insert(*n) {\n            dup = Some(*n);\n        }\n    }\n    match dup {\n        Some(v) => println!("{}", v),\n        None => println!("-1"),\n    }\n}\n',
