                                                                                                                                                                        (
                                                                                                                                                                            gen_random_uuid(),
                                                                                                                                                                            'Longest Palindromic Substring',
                                                                                                                                                                            ARRAY['strings', 'two-pointers'],
                                                                                                                                                                            'rust',
                                                                                                                                                                            'medium',
                                                                                                                                                                            'use std::io;\n\nfn expand(chars: &[char], mut l: i64, mut r: i64) -> (usize, usize) {\n    while l >= 0 && (r as usize) < chars.len() && chars[l as usize] == chars[r as usize] {\n        l -= 1;\n        r += 1;\n    }\n    ((l + 1) as usize, (r - 1) as usize)\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let s = input.trim();\n    let chars: Vec<char> = s.chars().collect();\n    if chars.is_empty() {\n        println!("");\n        return;\n    }\n    let (mut best_l, mut best_r) = (0usize, 0usize);\n    for i in 0..chars.len() {\n        let (l1, r1) = expand(&chars, i as i64, i as i64);\n        if r1 - l1 > best_r - best_l { best_l = l1; best_r = r1; }\n        if i + 1 < chars.len() {\n            let (l2, r2) = expand(&chars, i as i64, (i + 1) as i64);\n            if r2 >= l2 && r2 - l2 > best_r - best_l { best_l = l2; best_r = r2; }\n        }\n    }\n    println!("{}", &s[best_l..=best_r]);\n}\n',
                                                                                                                                                                            'use std::io;\n\nfn expand(chars: &[char], mut l: i64, mut r: i64) -> (usize, usize) {\n    while l >= 0 && (r as usize) < chars.len() && chars[l as usize] == chars[r as usize] {\n        l -= 1;\n        r += 1;\n    }\n    ((l + 1) as usize, (r - 1) as usize)\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let s = input.trim();\n    let chars: Vec<char> = s.chars().collect();\n    if chars.is_empty() {\n        println!("");\n        return;\n    }\n    let (mut best_l, mut best_r) = (0usize, 0usize);\n    for i in 0..chars.len() {\n        let (l1, r1) = expand(&chars, i as i64, i as i64);\n        if r1 - l1 > best_r - best_l { best_l = l1; best_r = r1; }\n    }\n    println!("{}", &s[best_l..=best_r]);\n}\n',
                                                                                                                                                                            '[{"input": "cbbd", "expected_output": "bb"}, {"input": "abccba", "expected_output": "abccba"}, {"input": "abba", "expected_output": "abba"}]'::jsonb,
