                                                                                                                                                                        (
                                                                                                                                                                            gen_random_uuid(),
                                                                                                                                                                            'Caesar Cipher',
                                                                                                                                                                            ARRAY['strings'],
                                                                                                                                                                            'rust',
                                                                                                                                                                            'easy',
                                                                                                                                                                            'use std::io;\n\nfn caesar(s: &str, k: i32) -> String {\n    let shift = ((k % 26) + 26) % 26;\n    s.chars().map(|c| {\n        if c.is_ascii_lowercase() {\n            (((c as u8 - b''a'' + shift as u8) % 26) + b''a'') as char\n        } else if c.is_ascii_uppercase() {\n            (((c as u8 - b''A'' + shift as u8) % 26) + b''A'') as char\n        } else {\n            c\n        }\n    }).collect()\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let k: i32 = input.trim().parse().unwrap();\n    let mut text = String::new();\n    io::stdin().read_line(&mut text).unwrap();\n    println!("{}", caesar(text.trim(), k));\n}\n',
                                                                                                                                                                            'use std::io;\n\nfn caesar(s: &str, k: i32) -> String {\n    s.chars().map(|c| {\n        if c.is_ascii_alphabetic() {\n            let base = b''a'';\n            let lower = c.to_ascii_lowercase() as u8;\n            (((lower - base) as i32 + k).rem_euclid(26) as u8 + base) as char\n        } else {\n            c\n        }\n    }).collect()\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let k: i32 = input.trim().parse().unwrap();\n    let mut text = String::new();\n    io::stdin().read_line(&mut text).unwrap();\n    println!("{}", caesar(text.trim(), k));\n}\n',
                                                                                                                                                                            '[{"input": "3\nHello World", "expected_output": "Khoor Zruog"}, {"input": "1\nABCxyz", "expected_output": "BCDyza"}, {"input": "13\nRust Lang", "expected_output": "Ehfg Ynat"}]'::jsonb,
                                                                                                                                                                            90,
