                                                                                                                                                                            'medium',
                                                                                                                                                                            'use std::io;\n\nstruct Node {\n    val: i64,\n    left: Option<Box<Node>>,\n    right: Option<Box<Node>>,\n}\n\nfn insert(root: &mut Option<Box<Node>>, v: i64) {\n    match root {\n        None => *root = Some(Box::new(Node { val: v, left: None, right: None })),\n        Some(n) => {\n            if v < n.val { insert(&mut n.left, v); }\n            else { insert(&mut n.right, v); }\n        }\n    }\n}\n\nfn inorder(root: &Option<Box<Node>>, out: &mut Vec<i64>) {\n    if let Some(n) = root {\n        inorder(&n.left, out);\n        out.push(n.val);\n        inorder(&n.right, out);\n    }\n}\n\nfn main() {\n    let mut line1 = String::new();\n    io::stdin().read_line(&mut line1).unwrap();\n    let k: usize = line1.trim().parse().unwrap();\n    let mut line2 = String::new();\n    io::stdin().read_line(&mut line2).unwrap();\n    let nums: Vec<i64> = line2.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let mut root: Option<Box<Node>> = None;\n    for n in nums { insert(&mut root, n); }\n    let mut sorted = Vec::new();\n    inorder(&root, &mut sorted);\n    println!("{}", sorted[k - 1]);\n}\n',
                                                                                                                                                                            'use std::io;\n\nstruct Node {\n    val: i64,\n    left: Option<Box<Node>>,\n    right: Option<Box<Node>>,\n}\n\nfn insert(root: &mut Option<Box<Node>>, v: i64) {\n    match root {\n        None => *root = Some(Box::new(Node { val: v, left: None, right: None })),\n        Some(n) => {\n            if v < n.val { insert(&mut n.left, v); }\n            else { insert(&mut n.right, v); }\n        }\n    }\n}\n\nfn traverse(root: &Option<Box<Node>>, out: &mut Vec<i64>) {\n    if let Some(n) = root {\n        out.push(n.val);\n        traverse(&n.left, out);\n        traverse(&n.right, out);\n    }\n}\n\nfn main() {\n    let mut line1 = String::new();\n    io::stdin().read_line(&mut line1).unwrap();\n    let k: usize = line1.trim().parse().unwrap();\n    let mut line2 = String::new();\n    io::stdin().read_line(&mut line2).unwrap();\n    let nums: Vec<i64> = line2.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let mut root: Option<Box<Node>> = None;\n    for n in nums { insert(&mut root, n); }\n    let mut sorted = Vec::new();\n    traverse(&root, &mut sorted);\n    println!("{}", sorted[k - 1]);\n}\n',
