                                                                                                                                                                            'use std::io;\n\nfn gen(open: i32, close: i32, current: String, result: &mut Vec<String>) {\n    if open == 0 && close == 0 {\n        result.push(current);\n        return;\n    }\n    if open > 0 {\n        gen(open - 1, close, current.clone() + "(", result);\n    }\n    if close > open {\n        gen(open, close - 1, current + ")", result);\n    }\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let n: i32 = input.trim().parse().unwrap();\n    let mut result = Vec::new();\n    gen(n, n, String::new(), &mut result);\n    result.sort();\n    println!("{}", result.join(" "));\n}\n',
