                                                                                                                                                                            'medium',
                                                                                                                                                                            'use std::io;\n\nfn has_cycle(node: usize, graph: &Vec<Vec<usize>>, state: &mut Vec<u8>) -> bool {\n    state[node] = 1;\n    for &next in &graph[node] {\n        if state[next] == 1 { return true; }\n        if state[next] == 0 && has_cycle(next, graph, state) { return true; }\n    }\n    state[node] = 2;\n    false\n}\n\nfn main() {\n    let mut line1 = String::new();\n    io::stdin().read_line(&mut line1).unwrap();\n    let parts: Vec<usize> = line1.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let (n, m) = (parts[0], parts[1]);\n    let mut graph = vec![Vec::new(); n];\n    for _ in 0..m {\n        let mut line = String::new();\n        io::stdin().read_line(&mut line).unwrap();\n        let edge: Vec<usize> = line.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n        graph[edge[0]].push(edge[1]);\n    }\n    let mut state = vec![0u8; n];\n    for i in 0..n {\n        if state[i] == 0 && has_cycle(i, &graph, &mut state) {\n            println!("yes");\n            return;\n        }\n    }\n    println!("no");\n}\n',
                                                                                                                                                                            'use std::io;\n\nfn has_cycle(node: usize, graph: &Vec<Vec<usize>>, visited: &mut Vec<bool>) -> bool {\n    if visited[node] { return true; }\n    visited[node] = true;\n    for &next in &graph[node] {\n        if has_cycle(next, graph, visited) { return true; }\n    }\n    false\n}\n\nfn main() {\n    let mut line1 = String::new();\n    io::stdin().read_line(&mut line1).unwrap();\n    let parts: Vec<usize> = line1.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let (n, m) = (parts[0], parts[1]);\n    let mut graph = vec![Vec::new(); n];\n    for _ in 0..m {\n        let mut line = String::new();\n        io::stdin().read_line(&mut line).unwrap();\n        let edge: Vec<usize> = line.trim().split_whitespace().map(|x| x.parse().unwrap()).collect();\n        graph[edge[0]].push(edge[1]);\n    }\n    let mut visited = vec![false; n];\n    for i in 0..n {\n        if !visited[i] && has_cycle(i, &graph, &mut visited) {\n            println!("yes");\n            return;\n        }\n    }\n    println!("no");\n}\n',
